DROP TABLE IF EXISTS `tensile_tests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tensile_tests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sample_id` bigint unsigned NOT NULL,
  `ys_mpa` decimal(8,2) DEFAULT NULL,
  `uts_mpa` decimal(8,2) DEFAULT NULL,
  `elong_pct` decimal(5,2) DEFAULT NULL,
  `ra_pct` decimal(5,2) DEFAULT NULL,
  `method_std` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ASTM E8',
  `specimen_dims` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pass_bool` tinyint(1) DEFAULT NULL,
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tensile_tests_sample_id_foreign` (`sample_id`),
  CONSTRAINT `tensile_tests_sample_id_foreign` FOREIGN KEY (`sample_id`) REFERENCES `samples` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7212 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
